  [("Cambiar la secuencia por completo para la persona que necesita adaptación.", "Se separa a la persona del grupo.", "Cambia solo un detalle y mantén el mismo compás."), ("Seguir bailando cuando alguien se choca.", "Puede haber un golpe o una caída.", "Detente, pregunta si está bien y vuelve a empezar.")],
